tests:
test('factorial of 0 is 1', () => { assert.equal(factorial(0), 1); });
test('factorial of 1 is 1', () => { assert.equal(factorial(1), 1); });
test('factorial of 4', () => { assert.equal(factorial(4), 24); });
test('factorial of 6', () => { assert.equal(factorial(6), 720); });

referenceSolution:
function factorial(n) {
  if (n <= 1) {
    return 1;
  }
  return n * factorial(n - 1);
}
